const input = $json.body ?? $json;
const num = (v) => {
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
};
const baseMao = num(input.base_mao ?? input.baseMAO);
const factor = num(input.calibration_factor ?? input.adjustment_factor);
const confidence = String(input.confidence ?? "").toLowerCase();
const calibrationStatus = String(input.calibration_status ?? "").toLowerCase();
const assetType = String(input.asset_type ?? input.property_type ?? "").toLowerCase();
const dealId = input.deal_id;
const leadId = input.lead_id;
const propertyId = input.property_id;
const blockers = Array.isArray(input.blockers) ? input.blockers : [];
const dnc = input.dnc === true || input.do_not_contact === true;

const assetClass =
  assetType.includes("land") ? "land" :
  assetType.includes("multi") || assetType.includes("apartment") ? "multifamily" :
  "residential_wholesale";

const validFactor = factor !== null && factor > 0 && factor <= 1.25;
const validBaseMao = baseMao !== null && baseMao >= 0;
const identityReady = Boolean(dealId && leadId && propertyId);
const calibrationReady = calibrationStatus === "calibration_ready";
const confidenceReady = ["high", "medium"].includes(confidence);
const blocked = dnc || blockers.length > 0;

let strategy = "asset_specific_economics";
if (assetClass === "land") strategy = "land_development_and_exit_economics";
if (assetClass === "multifamily") strategy = "multifamily_cashflow_and_exit_economics";
if (assetClass === "residential_wholesale") strategy = "residential_wholesale_assignment_economics";

const adjustedMao = validBaseMao && validFactor ? Math.round(baseMao * factor * 100) / 100 : null;

let status = "strategy_adjusted";
let nextWorkflow = "WF-333";
let reason = "Calibration is valid and confidence is sufficient for an asset-aware MAO adjustment.";
if (!calibrationReady || !identityReady || !validBaseMao || !validFactor) {
  status = "incomplete_calibration";
  nextWorkflow = "WF-331";
  reason = "Required calibration identity, status, base MAO, or calibration factor is missing/invalid.";
} else if (blocked) {
  status = "blocked";
  nextWorkflow = "WF-126";
  reason = "DNC or active blockers prevent autonomous strategy adjustment.";
} else if (!confidenceReady) {
  status = "human_review_required";
  nextWorkflow = "WF-126";
  reason = "Calibration confidence is insufficient for autonomous MAO adjustment.";
}

return [{
  json: {
    ...input,
    workflow_id: "WF-332",
    controller_status: status,
    calibration_status: calibrationStatus,
    deal_id: dealId,
    lead_id: leadId,
    property_id: propertyId,
    asset_class: assetClass,
    strategy,
    base_mao: baseMao,
    calibration_factor: factor,
    adjusted_mao: adjustedMao,
    confidence,
    rule_70_percent: "secondary_reference_only",
    economics_priority: "asset_specific_first",
    reason,
    next_workflow: nextWorkflow,
    requires_human_review: status === "human_review_required" || status === "blocked",
    idempotency_key: input.idempotency_key ?? \`wf-332:\${dealId ?? "unknown"}:\${propertyId ?? "unknown"}:\${factor ?? "unknown"}\`
  }
}];
